from pathlib import Path
import base64
import re

TEXT_FILES = {'apps/processes/__init__.py': '', 'apps/processes/apps.py': '', 'apps/processes/models.py': '', 'apps/processes/signals.py': '', 'apps/processes/forms.py': '', 'apps/processes/services.py': '', 'apps/processes/selectors.py': '', 'apps/processes/views.py': '', 'apps/processes/urls.py': '', 'apps/processes/admin.py': '', 'apps/processes/migrations/__init__.py': '', 'apps/processes/management/__init__.py': '', 'apps/processes/management/commands/__init__.py': '', 'apps/processes/management/commands/seed_process_map.py': '', 'templates/processes/map.html': '', 'templates/processes/process_form.html': '', 'templates/processes/detail.html': '', 'templates/processes/reference_upload.html': '', 'static/css/processes_v71.css': '', 'static/js/processes_v71.js': ''}

BINARY_FILES = {'imports/01 - Documento_sobre_el_alcance_del_SGSI_V0.13.pdf': '', 'imports/02 - MAPA DE PROCESOS SIEMPRESOFT_V0.14.pdf': ''}


def backup_and_write_text(path, content):
    path.parent.mkdir(parents=True, exist_ok=True)

    if path.exists():
        backup = path.with_name(
            path.name + ".before_processes_v71.bak"
        )

        if not backup.exists():
            backup.write_text(
                path.read_text(encoding="utf-8"),
                encoding="utf-8",
            )

    path.write_text(content, encoding="utf-8")


print("=== PROCESOS V71 ===")

for filename, encoded in TEXT_FILES.items():
    path = Path(filename)
    content = base64.b64decode(encoded).decode("utf-8")
    backup_and_write_text(path, content)
    print("OK:", filename)


for filename, encoded in BINARY_FILES.items():
    path = Path(filename)
    path.parent.mkdir(parents=True, exist_ok=True)

    if not path.exists():
        path.write_bytes(base64.b64decode(encoded))
        print("OK:", filename)
    else:
        print("EXISTE:", filename)


settings_candidates = [
    Path("config/settings/base.py"),
    Path("config/settings.py"),
]

settings = next(
    (item for item in settings_candidates if item.exists()),
    None,
)

if settings is None:
    raise SystemExit(
        "ERROR: no se encontró el archivo de settings."
    )

text = settings.read_text(encoding="utf-8")
app_ref = '"apps.processes.apps.ProcessesConfig",'

if app_ref not in text:
    anchors = [
        '"apps.organization.apps.OrganizationConfig",',
        '"apps.context42.apps.Context42Config",',
        '"apps.dashboard.apps.DashboardConfig",',
    ]

    anchor = next(
        (item for item in anchors if item in text),
        None,
    )

    if anchor:
        text = text.replace(
            anchor,
            anchor + "\n    " + app_ref,
            1,
        )
    else:
        match = re.search(
            r"INSTALLED_APPS\s*=\s*\[\s*\n",
            text,
        )

        if not match:
            raise SystemExit(
                "ERROR: no se pudo localizar INSTALLED_APPS."
            )

        pos = match.end()
        text = (
            text[:pos]
            + "    "
            + app_ref
            + "\n"
            + text[pos:]
        )

    settings.write_text(text, encoding="utf-8")
    print("OK: ProcessesConfig registrado")
else:
    print("OK: ProcessesConfig ya registrado")


urls = Path("config/urls.py")

if not urls.exists():
    raise SystemExit(
        "ERROR: no existe config/urls.py"
    )

url_text = urls.read_text(encoding="utf-8")

if 'include("apps.processes.urls")' not in url_text:
    match = re.search(
        r"urlpatterns\s*=\s*\[\s*\n",
        url_text,
    )

    if not match:
        raise SystemExit(
            "ERROR: no se encontró urlpatterns."
        )

    pos = match.end()

    url_text = (
        url_text[:pos]
        + '    path("", include("apps.processes.urls")),\n'
        + url_text[pos:]
    )

    urls.write_text(url_text, encoding="utf-8")
    print("OK: rutas de Procesos registradas")
else:
    print("OK: rutas de Procesos ya registradas")


base = Path("templates/base.html")

if base.exists():
    base_text = base.read_text(encoding="utf-8")

    if "{% url 'processes:map' %}" not in base_text:
        patterns = [
            r'(<a[^>]+href="\{% url \'organization:chart\' %\}"[^>]*>.*?</a>)',
            r'(<a[^>]+href="/organizacion/"[^>]*>.*?</a>)',
        ]

        inserted = False

        for pattern in patterns:
            match = re.search(
                pattern,
                base_text,
                flags=re.DOTALL,
            )

            if match:
                process_link = (
                    '\n        <a class="management-link" '
                    'href="{% url \'processes:map\' %}">'
                    '<span>⇄</span>Procesos</a>'
                )

                base_text = (
                    base_text[:match.end()]
                    + process_link
                    + base_text[match.end():]
                )

                inserted = True
                break

        if inserted:
            backup = base.with_name(
                base.name + ".before_processes_v71.bak"
            )

            if not backup.exists():
                backup.write_text(
                    base.read_text(encoding="utf-8"),
                    encoding="utf-8",
                )

            base.write_text(
                base_text,
                encoding="utf-8",
            )

            print(
                "OK: Procesos agregado debajo de Organización"
            )
        else:
            print(
                "ADVERTENCIA: no se encontró el enlace Organización "
                "para insertar Procesos automáticamente."
            )
    else:
        print("OK: menú Procesos ya existe")


